const cache = new Map<string, ChapterData>();

function loadBook(translationId: string, bookId: string): ChapterData | null {
  const key = `${translationId}:${bookId}`;
  const cached = cache.get(key);
  if (cached) return cached;

  const loader = LOADERS[translationId]?.[bookId];
  if (!loader) return null;

  const data = loader();
  cache.set(key, data);
  return data;
}

/**
 * Verse strings for a chapter, or null when the reference does not exist.
 *
 * Defaults to the KJV, which is also what callers use as the fallback when a
 * remote translation cannot be loaded.
 */
export function getOfflineChapter(
  bookId: string,
  chapter: number,
  translationId: string = DEFAULT_TRANSLATION
): string[] | null {
  const book = loadBook(translationId, bookId);
  if (!book) return null;

  const verses = book[chapter - 1] ?? null;
  // A translation may leave a verse number unused where it merges two verses.
  return verses ? verses.filter((verse) => verse.length > 0) : null;
}

export function hasOfflineBook(
  bookId: string,
  translationId: string = DEFAULT_TRANSLATION
): boolean {
  return Boolean(LOADERS[translationId]?.[bookId]);
}

/** True when the whole translation ships with the app. */
export function isBundledTranslation(translationId: string): boolean {
  return translationId in LOADERS;
}
